/**
 * Storage keys of a gallery's photos (plan p05, D5.7). IMPORT-FREE: the relay (purge), `worker.ts`
 * (plan p06) and the browser build the same keys. Generated by server code from ids and server-minted
 * values, never from a filename.
 *
 * - original, in `memoria-originals`: `galleries/<galleryId>/<photoId>/original.<jpg|png|webp>`
 * - derivatives, in `memoria-media`: `galleries/<galleryId>/<photoId>/<rev>/thumb.<webp|jpg>` and
 *   `…/display.<ext>`; `rev` changes when a photo is replaced or reprocessed, so the CDN never serves
 *   a stale copy.
 */

export type OriginalType = 'image/jpeg' | 'image/png' | 'image/webp';
export type DerivativeExtension = 'webp' | 'jpg';

const ORIGINAL_EXT: Record<OriginalType, string> = { 'image/jpeg': 'jpg', 'image/png': 'png', 'image/webp': 'webp' };

export const REV_RE = /^[a-z2-9]{8}$/;

export function originalKey(galleryId: string, photoId: string, contentType: OriginalType): string {
  return `galleries/${galleryId}/${photoId}/original.${ORIGINAL_EXT[contentType]}`;
}

export function thumbKey(galleryId: string, photoId: string, rev: string, ext: DerivativeExtension): string {
  return `galleries/${galleryId}/${photoId}/${rev}/thumb.${ext}`;
}

export function displayKey(galleryId: string, photoId: string, rev: string, ext: DerivativeExtension): string {
  return `galleries/${galleryId}/${photoId}/${rev}/display.${ext}`;
}

export type PhotoKeySource = { id: string; gallery_id: string; content_type: OriginalType; rev: string; derivative_ext: DerivativeExtension };

/** The three objects of a photo: `original` in the originals bucket, `thumb` and `display` in media. */
export function photoKeys(photo: PhotoKeySource): { original: string; thumb: string; display: string } {
  return {
    original: originalKey(photo.gallery_id, photo.id, photo.content_type),
    thumb: thumbKey(photo.gallery_id, photo.id, photo.rev, photo.derivative_ext),
    display: displayKey(photo.gallery_id, photo.id, photo.rev, photo.derivative_ext),
  };
}

/** 8 characters of `[a-z2-9]` (ck_photos_rev) from `crypto.getRandomValues`. */
export function newRev(): string {
  return randomString(8);
}

/** `n` characters of `[a-z2-9]`, uniform (rejection sampling). Also the slug's random part. */
export function randomString(n: number): string {
  const chars = 'abcdefghijklmnopqrstuvwxyz23456789'; // 34 characters
  let out = '';
  while (out.length < n) {
    const bytes = crypto.getRandomValues(new Uint8Array(n * 2));
    for (const b of bytes) {
      if (b >= 34 * 7) continue; // 238: the largest multiple of 34 below 256
      out += chars[b % 34];
      if (out.length === n) break;
    }
  }
  return out;
}
